def seed_ai_actions(apps, schema_editor):
    AiAction = apps.get_model('core', 'AiAction')
    AiModel = apps.get_model('core', 'AiModel')
    for purpose, label, slug, effort in ACTIONS:
        AiAction.objects.get_or_create(purpose=purpose, defaults={
            'label': label, 'modality': 'text', 'effort': effort,
            'model': AiModel.objects.filter(slug=slug, status='active').first(),
        })


